import{_ as m,C as o,o as g,c as b,j as t,a,E as s,a8 as v}from"./chunks/framework.27XeWUA0.js";const r="/schedule-dashboard/thumbs/yt/Wk2bUUGFC_o-640.webp",y="/schedule-dashboard/thumbs/yt/Wk2bUUGFC_o-1280.webp",n="/schedule-dashboard/thumbs/yt/Ve2bAarPA2I-640.webp",f="/schedule-dashboard/thumbs/yt/Ve2bAarPA2I-1280.webp",i="/schedule-dashboard/thumbs/yt/mMw3arwQsL0-640.webp",k="/schedule-dashboard/thumbs/yt/mMw3arwQsL0-1280.webp",l="/schedule-dashboard/thumbs/yt/c_SPW__jF9w-640.webp",_="/schedule-dashboard/thumbs/yt/c_SPW__jF9w-1280.webp",h="/schedule-dashboard/thumbs/yt/_dTF3NpPzGo-640.webp",A="/schedule-dashboard/thumbs/yt/_dTF3NpPzGo-1280.webp",c="/schedule-dashboard/thumbs/yt/yW1RnJ5oaMk-640.webp",P="/schedule-dashboard/thumbs/yt/yW1RnJ5oaMk-1280.webp",w="/schedule-dashboard/thumbs/yt/PQN76wcEt10-640.webp",I="/schedule-dashboard/thumbs/yt/PQN76wcEt10-1280.webp",d="/schedule-dashboard/thumbs/yt/Gxi_n-PtQBo-640.webp",S="/schedule-dashboard/thumbs/yt/Gxi_n-PtQBo-1280.webp",J=JSON.parse('{"title":"AI Digest · Fri 23 Oct 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-10-23","routine":"digest"},"relativePath":"digest/2026-10-23.md","filePath":"digest/[date].md"}'),W={name:"digest/2026-10-23.md"},x=r+" 640w, "+y+" 1280w",C=n+" 640w, "+f+" 1280w",T=i+" 640w, "+k+" 1280w",G=l+" 640w, "+_+" 1280w",F=h+" 640w, "+A+" 1280w",M=c+" 640w, "+P+" 1280w",N=w+" 640w, "+I+" 1280w",E=d+" 640w, "+S+" 1280w",Q={id:"ai-digest-·-fri-23-oct-2026",tabindex:"-1"};function U(B,e,L,V,z,O){const p=o("Badge"),u=o("DayFilter");return g(),b("div",null,[t("h1",Q,[e[0]||(e[0]=a("AI Digest · Fri 23 Oct 2026 ",-1)),s(p,{type:"tip",text:"8"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-fri-23-oct-2026","aria-label":'Permalink to "AI Digest · Fri 23 Oct 2026 <Badge type="tip" text="8" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 23 Oct 2026 · run date Fri 23 Oct 2026 · 8 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(" 5 new talks in the last 24 hours, all with full transcripts. Freshest are Evan Conrad on why GPU credit could wipe out AI startups (4:30 AM IST) and Jellyfish's data showing the model barely affects engineering output (12:30 AM IST). The two eval talks from New York Life and Air Canada cover well-trodden 'evals for agents' ground (seen 34 times), though each has new specifics, and Tone-Bench on AI writing is fresh.")]),t("p",null,[t("strong",null,"Better Stack:"),a(" 3 new videos, all with transcripts and none mostly repeats: the eMudhra 'private key of 4' certificate mess (freshest, 2:30 AM IST), God's Eye View, an open-source live-data globe, and the PHP2Shell bug that took sites offline.")])],-1)),s(u),e[5]||(e[5]=v('<div class="grid cards2"><article class="it full" id="v-Wk2bUUGFC_o" data-title="Why AI Startups Will Disappear Without Compute Markets — Evan Conrad, San Francisco Compute" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=Wk2bUUGFC_o" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+x+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o" target="_blank" rel="noopener">Why AI Startups Will Disappear Without Compute Markets — Evan Conrad, San Francisco Compute</a></h3><div class="meta">AI Engineer · Evan Conrad, San Francisco Compute · uploaded 23 Oct, 4:30 AM IST · 17:49</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — a clear, non-repeat explanation of why GPU financing, not power, gates new AI companies.</div><p class="note">---</p><div class="sh">How SF Compute got here</div><ul><li><strong>Operator and market in one:</strong> SF Compute runs GPU clusters for data-center owners and VCs (&quot;supercomputing as a service&quot;) and, on top, a live order book where you can buy reserved capacity now or in the future, which he calls a physically settled forwards market (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=42s" target="_blank" rel="noopener">0:42</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=212s" target="_blank" rel="noopener">3:32</a>)</li><li><strong>Forced into brokering:</strong> They started as Junlark, a music-AI lab before Suno/Udio; they raised $500k against a typical $10M deposit, went underwater on a cluster and had to sublease it to avoid bankruptcy, which made them the first GPU broker (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=128s" target="_blank" rel="noopener">2:08</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=212s" target="_blank" rel="noopener">3:32</a>)</li></ul><div class="sh">Why it&#39;s one risk problem</div><ul><li><strong>Sold out, deposits, delays:</strong> Everyone is sold out, a new cluster has a lead time, you pay your whole bank balance as a deposit because lenders can&#39;t underwrite &quot;superintelligence&quot;, and clusters land late because they&#39;re only built after a customer signs (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=266s" target="_blank" rel="noopener">4:26</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=380s" target="_blank" rel="noopener">6:20</a>)</li><li><strong>AI can&#39;t absorb price shocks:</strong> A SaaS company survives its cloud doubling prices; an AI company goes bankrupt or leaves, so GPUs can&#39;t be sold on demand and need long take-or-pay contracts, which in turn lock out a fast-growing customer who needs capacity now (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=380s" target="_blank" rel="noopener">6:20</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=493s" target="_blank" rel="noopener">8:13</a>)</li><li><strong>Credit, not power:</strong> He says credit is AI&#39;s number-one bottleneck and you hit it long before power; VCs end up funding capex indirectly through the deposits their startups send to clouds (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=493s" target="_blank" rel="noopener">8:13</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=613s" target="_blank" rel="noopener">10:13</a>)</li></ul><div class="sh">What a market needs</div><ul><li><strong>You must run the hotel:</strong> GPU compute isn&#39;t standardized enough to separate the market from the hardware; like reselling a hotel room, you can&#39;t fix anything you don&#39;t operate, so pure brokering fails (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=697s" target="_blank" rel="noopener">11:37</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=785s" target="_blank" rel="noopener">13:05</a>)</li><li><strong>Why nobody else does it:</strong> Building physical settlement means building a full GPU cloud, and then signing billion-dollar deals as a cloud is more lucrative than running a market (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=785s" target="_blank" rel="noopener">13:05</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=839s" target="_blank" rel="noopener">13:59</a>)</li><li><strong>$10M to $1B deposits:</strong> The ante for a new lab went from $10M to $100M to about $1B; if inference providers push credit risk down to app builders (5-year token contracts, big deposits), he predicts new startups would need ~$100M of tokens and the industry consolidates like TSMC (<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=839s" target="_blank" rel="noopener">13:59</a>–<a href="https://www.youtube.com/watch?v=Wk2bUUGFC_o&amp;t=1069s" target="_blank" rel="noopener">17:49</a>)</li></ul></div></article><article class="it full" id="v-Ve2bAarPA2I" data-title="Better AI Models Won&#39;t Fix Your Engineering Team — Nicholas Arcolano, Jellyfish" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=Ve2bAarPA2I" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+C+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=Ve2bAarPA2I" target="_blank" rel="noopener">Better AI Models Won&#39;t Fix Your Engineering Team — Nicholas Arcolano, Jellyfish</a></h3><div class="meta">AI Engineer · Nicholas Arcolano, head of AI and research, Jellyfish · uploaded 23 Oct, 12:30 AM IST · 16:39</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — hard numbers on model vs skills vs people, and the skills finding is useful for Milan&#39;s own setup.</div><div class="repeat">🔁 Repeat: &#39;AI ROI measurement&#39; — seen 6 times before (including Jellyfish&#39;s own &quot;Tokens Are the Cheap Part&quot;). New here: a breakdown of what actually explains PR throughput, with the model/tool at under 1%.</div><p class="note">---</p><div class="sh">The model barely matters</div><ul><li><strong>The Grok natural experiment:</strong> Around SpaceX&#39;s Cursor acquisition, Cursor promoted Grok in its UI and auto mode, giving the fastest model-share shift Jellyfish has seen; engineers&#39; merged PRs showed no correlation with how far they moved to Grok (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=179s" target="_blank" rel="noopener">2:59</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=294s" target="_blank" rel="noopener">4:54</a>)</li><li><strong>Switching tools is a &quot;nothingburger&quot;:</strong> Comparing engineers to themselves when they switch Opus vs Sonnet, to ChatGPT, Cursor to Claude Code, or autocomplete to agentic mode shows no meaningful throughput change (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=434s" target="_blank" rel="noopener">7:14</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=487s" target="_blank" rel="noopener">8:07</a>)</li></ul><div class="sh">What does drive output (≈50,000 engineers, 447 companies)</div><ul><li><strong>The pie chart:</strong> Of the variation in merged PRs per engineer per week, the tool explains under 1%, skill use about 3%, token usage about 9%, company and team about 12%, and the individual engineer roughly three quarters (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=294s" target="_blank" rel="noopener">4:54</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=434s" target="_blank" rel="noopener">7:14</a>)</li><li><strong>Skills move output more than models:</strong> Almost half of engineer-weeks in September had zero skill use and only 12% used skills heavily, but 30+ skill runs per engineer per week gives about a 30% bump with everything else held constant (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=487s" target="_blank" rel="noopener">8:07</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=600s" target="_blank" rel="noopener">10:00</a>)</li><li><strong>Tokens have diminishing returns:</strong> Going from median to top-10% token use roughly doubles output but costs about 10x the tokens (repeat of his World&#39;s Fair talk) (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=600s" target="_blank" rel="noopener">10:00</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=683s" target="_blank" rel="noopener">11:23</a>)</li><li><strong>Company spread is 2x:</strong> At fixed AI spend the top-10% company gets twice the output of the bottom-10%; about two-thirds of that is the company and one-third the team (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=683s" target="_blank" rel="noopener">11:23</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=742s" target="_blank" rel="noopener">12:22</a>)</li></ul><div class="sh">People</div><ul><li><strong>Top engineers stay top:</strong> Individual spread is 3.5x; about 44% of top-quartile engineers cycled out every half year before AI and 41% after, so AI isn&#39;t re-sorting who the best engineers are (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=742s" target="_blank" rel="noopener">12:22</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=890s" target="_blank" rel="noopener">14:50</a>)</li><li><strong>Leaders&#39; lever:</strong> Leaders can&#39;t change the models but can change the &quot;course&quot;: codebase, review process and culture (<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=890s" target="_blank" rel="noopener">14:50</a>–<a href="https://www.youtube.com/watch?v=Ve2bAarPA2I&amp;t=998s" target="_blank" rel="noopener">16:38</a>)</li></ul></div></article><article class="it full" id="v-mMw3arwQsL0" data-title="1,368 AI Failures and What They Teach About Evals — Vishal Srivastava &amp; Tanmay Sah, New York Life" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=mMw3arwQsL0" target="_blank" rel="noopener"><img src="'+i+'" srcset="'+T+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=mMw3arwQsL0" target="_blank" rel="noopener">1,368 AI Failures and What They Teach About Evals — Vishal Srivastava &amp; Tanmay Sah, New York Life</a></h3><div class="meta">AI Engineer · Vishal Srivastava &amp; Tanmay Sah, New York Life · uploaded 22 Oct, 2:30 PM IST · 20:02</div><div class="verdict v-skim"><b>Verdict:</b> skim from 6:09 — the incident-derived harm ranking is new; the eval process itself is familiar ground.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 34 times before. New here: the evals are derived from 1,368 real incidents in the public AI Incident Database, with a harm ranking of failure types.</div><div class="repeat">🔁 Repeat: &#39;AI in regulated industries&#39; — seen 13 times before. New here: a materiality scale for ranking which use cases get the most testing.</div><p class="note">---</p><div class="sh">What real failures look like</div><ul><li><strong>Failures are exploding:</strong> Incidents in the AI Incident Database have risen almost vertically in the last four years of the foundation-model era, faster than enterprises can review use cases one by one (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=41s" target="_blank" rel="noopener">0:41</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=95s" target="_blank" rel="noopener">1:35</a>)</li><li><strong>Three dimensions, 13 sub-dimensions:</strong> Technical strength (data quality, system design, predictive validity, fairness, failure modes, explainability), deployment controls (decision authority, human mediation, exposure control, monitoring) and business impact (financial, legal, scale) (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=95s" target="_blank" rel="noopener">1:35</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=369s" target="_blank" rel="noopener">6:09</a>)</li><li><strong>98% coverage, ~6 per incident:</strong> These 13 sub-dimensions cover about 98% of incidents, and an average incident involves six of them at once (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=369s" target="_blank" rel="noopener">6:09</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=432s" target="_blank" rel="noopener">7:12</a>)</li><li><strong>Deployment controls cause the most harm:</strong> Weak human-in-the-loop and missing harm detection are most associated with harm, while scale and system design are frequent but less harmful; as a group, deployment controls outrank business impact, which outranks technical failure (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=432s" target="_blank" rel="noopener">7:12</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=583s" target="_blank" rel="noopener">9:43</a>)</li></ul><div class="sh">Turning it into evals</div><ul><li><strong>Risk in four parts:</strong> How often the model fails, whether the failure reaches a real decision, whether it goes uncaught, and how severe it is, so the same model carries different risk depending on deployment (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=643s" target="_blank" rel="noopener">10:43</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=700s" target="_blank" rel="noopener">11:40</a>)</li><li><strong>Test the whole system and the judge:</strong> Check retrieval, tool failures, whether human review catches mistakes and whether the agent stays in its permissions, and treat the AI judge as something you govern because it can be wrong too (repeat) (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=700s" target="_blank" rel="noopener">11:40</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=828s" target="_blank" rel="noopener">13:48</a>)</li><li><strong>Falsify, don&#39;t confirm:</strong> Citing Peter Wason&#39;s 2-4-6 experiment (79% tested wrongly), they argue for failure-driven &quot;build, break, fix&quot; evals that map where the system can and can&#39;t be trusted (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=828s" target="_blank" rel="noopener">13:48</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=1023s" target="_blank" rel="noopener">17:03</a>)</li><li><strong>The airline chatbot case:</strong> A chatbot told a bereaved customer he could claim a discount within 90 days after buying; the tribunal held the airline liable, and a policy-match requirement plus adversarial refund questions would have caught it (<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=1023s" target="_blank" rel="noopener">17:03</a>–<a href="https://www.youtube.com/watch?v=mMw3arwQsL0&amp;t=1110s" target="_blank" rel="noopener">18:30</a>)</li></ul></div></article><article class="it full" id="v-c_SPW__jF9w" data-title="How to Test AI Agents When No Benchmark Exists — Nathanael Weill, Air Canada" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=c_SPW__jF9w" target="_blank" rel="noopener"><img src="'+l+'" srcset="'+G+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=c_SPW__jF9w" target="_blank" rel="noopener">How to Test AI Agents When No Benchmark Exists — Nathanael Weill, Air Canada</a></h3><div class="meta">AI Engineer · Nathanael Weill, Air Canada · uploaded 22 Oct, 1:30 PM IST · 19:50</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:00 — the contract test-generation tricks are practical and new; the RAG part is well-known.</div><div class="repeat">🔁 Repeat: &#39;evals for agents&#39; — seen 34 times before. New here: five concrete ways to generate tests with known answers for a supplier-contract agent.</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 5 times before. New here: he avoided judges entirely because their noise rivaled the agent&#39;s.</div><p class="note">---</p><div class="sh">The lesson from RAG (2024)</div><ul><li><strong>One eval a week:</strong> At a telecom company with about 10,000 documents, his team graded chatbots in weekly meetings with experts in front of a big screen, and experts often disagreed (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=60s" target="_blank" rel="noopener">1:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=360s" target="_blank" rel="noopener">6:00</a>)</li><li><strong>Invert the problem:</strong> Have an LLM write a question from a known page, then check by code whether retrieval finds that page; this took them from one eval a week to dozens a day, and removing complexity and tuning embeddings, chunking and the BM25 alpha helped most (repeat) (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=360s" target="_blank" rel="noopener">6:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=480s" target="_blank" rel="noopener">8:00</a>)</li></ul><div class="sh">Air Canada&#39;s contract agent (2026)</div><ul><li><strong>The task:</strong> An agent that spots non-compliant clauses in supplier contracts, finds supporting documents, drafts amendments and classifies whether to keep them, with no public benchmark and busy, expensive legal experts (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=480s" target="_blank" rel="noopener">8:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=660s" target="_blank" rel="noopener">11:00</a>)</li><li><strong>Planting rule breaks:</strong> Diffing original vs signed contracts failed because teams don&#39;t keep versions, so they wrote clauses violating known rules (e.g. a cap above $1M) and generated contracts around them, yielding 275 tests with known answers (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=720s" target="_blank" rel="noopener">12:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=840s" target="_blank" rel="noopener">14:00</a>)</li><li><strong>Remove a clause:</strong> Deleting a clause from a signed contract was the hardest test; the agent missed most removed clauses, making it their strongest benchmark (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=840s" target="_blank" rel="noopener">14:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=900s" target="_blank" rel="noopener">15:00</a>)</li><li><strong>Invariance and templates:</strong> Changing supplier names or addresses, reordering clauses or rerunning must not change the flags, and filling experts&#39; contract templates from arrays of values produces many contracts with known breaches, all checked by code in about 5 minutes (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=900s" target="_blank" rel="noopener">15:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=1020s" target="_blank" rel="noopener">17:00</a>)</li><li><strong>Expert feedback improves tests, not the agent:</strong> They even redesigned the agent so it could be evaluated, and expert feedback goes into better test generation (<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=1080s" target="_blank" rel="noopener">18:00</a>–<a href="https://www.youtube.com/watch?v=c_SPW__jF9w&amp;t=1140s" target="_blank" rel="noopener">19:00</a>)</li></ul></div></article><article class="it full" id="v-_dTF3NpPzGo" data-title="Why AI Writing Still Reads Like Slop — Louis-François Bouchard, Towards AI" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=_dTF3NpPzGo" target="_blank" rel="noopener"><img src="'+h+'" srcset="'+F+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=_dTF3NpPzGo" target="_blank" rel="noopener">Why AI Writing Still Reads Like Slop — Louis-François Bouchard, Towards AI</a></h3><div class="meta">AI Engineer · Louis-François Bouchard, Towards AI · uploaded 22 Oct, 12:30 PM IST · 19:02</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — fresh ground (writing quality, not code), with a concrete recipe for less sloppy AI drafts.</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 5 times before. New here: evidence that judges favor their own model family, OpenAI most strongly.</div><div class="sh">What slop is</div><ul><li><strong>Six traits:</strong> Overused words like &quot;delve&quot;, vague generalities, saying nothing, repeating itself, hallucinating, and having no voice (or everyone&#39;s at once), and he says it keeps scaling even with GPT-6.1-class models (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=0s" target="_blank" rel="noopener">0:00</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=161s" target="_blank" rel="noopener">2:41</a>)</li></ul><div class="sh">Tone-Bench</div><ul><li><strong>Can a model write like him:</strong> A new benchmark, released with this talk, that gives models a long brief, research and examples of his style and asks for a full video script he could read aloud without cringing (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=344s" target="_blank" rel="noopener">5:44</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=439s" target="_blank" rel="noopener">7:19</a>)</li><li><strong>10 scripts, 5 drafts, 4 judges:</strong> Each model writes 5 drafts per script to measure variance (Grok 4.7 matched Opus 5.5 on only one draft in five) across about 120 models, scored by 4 LLM judges (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=439s" target="_blank" rel="noopener">7:19</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=554s" target="_blank" rel="noopener">9:14</a>)</li><li><strong>What&#39;s scored:</strong> Nine metrics in five groups: tone/voice, writing quality (hooks, transitions), instruction following, research accuracy, and slop (EQ-Bench slop score plus their own), from a ~14,000-token judge prompt that categorizes first, then rates (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=554s" target="_blank" rel="noopener">9:14</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=758s" target="_blank" rel="noopener">12:38</a>)</li><li><strong>Judges prefer themselves:</strong> Most judges favor their own family, OpenAI especially, and Anthropic and OpenAI seem to rate each other down, so he checked with 1,000 human A/B pairs from himself and three teammates (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=758s" target="_blank" rel="noopener">12:38</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=855s" target="_blank" rel="noopener">14:15</a>)</li><li><strong>The cost:</strong> About 500 hours to build, four months on four &quot;20x&quot; subscriptions, and over $2,000 to change one rubric line or over $4,000 to change one generation prompt line (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=855s" target="_blank" rel="noopener">14:15</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=920s" target="_blank" rel="noopener">15:20</a>)</li></ul><div class="sh">How to write better with AI</div><ul><li><strong>Cheap drafts, smart merge:</strong> GLM 5.3 Flash is very good and about 50x cheaper than the top model, Opus 5.5 extra-high (which matches Max thinking at 2.5x less); he suggests ~10 cheap drafts merged by a high-thinking model, one to three review passes only, very long prompts with positive and negative examples, and a final human review (<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=920s" target="_blank" rel="noopener">15:20</a>–<a href="https://www.youtube.com/watch?v=_dTF3NpPzGo&amp;t=1142s" target="_blank" rel="noopener">19:02</a>)</li></ul></div></article><article class="it full" id="v-yW1RnJ5oaMk" data-title="A Certificate Authority Just Got Caught Using a Private Key of 4" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=yW1RnJ5oaMk" target="_blank" rel="noopener"><img src="'+c+'" srcset="'+M+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk" target="_blank" rel="noopener">A Certificate Authority Just Got Caught Using a Private Key of 4</a></h3><div class="meta">Better Stack · Andress · uploaded 23 Oct, 2:30 AM IST · 8:02</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — new, and the CI/certifi fix is directly actionable.</div><p class="note">---</p><div class="sh">What happened</div><ul><li><strong>Eight weak eMudhra keys:</strong> On 17 Oct a researcher named Wayne reported that eight eMudhra intermediate CAs (six TLS, two code signing), created April 2025 and cross-signed by Sectigo, had compromised private keys; Chrome and Firefox blocked them within hours, Apple and Microsoft within 3 days (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=40s" target="_blank" rel="noopener">0:40</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=81s" target="_blank" rel="noopener">1:21</a>)</li><li><strong>A key of 4:</strong> P-384 private keys should be random 384-bit numbers (~10^115 options), but these were 47 zero bytes plus one byte; his Python script recovered all eight (4, 56, 66, 115, 155, 156, 230, 237) in under a second, and nothing looked structurally broken (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=81s" target="_blank" rel="noopener">1:21</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=167s" target="_blank" rel="noopener">2:47</a>)</li><li><strong>How:</strong> A changed key ceremony to test key export created a second weak key pair on the HSM with a similar name, and someone picked the wrong one; in June 2025 Sectigo flagged invalid CRL signatures, and eMudhra re-signed with the weak keys instead of investigating, so it could have been caught 16 months earlier (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=167s" target="_blank" rel="noopener">2:47</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=226s" target="_blank" rel="noopener">3:46</a>)</li></ul><div class="sh">Who&#39;s exposed</div><ul><li><strong>Browsers fine, tools not:</strong> None of these certs appeared in Certificate Transparency logs, which browsers require, but curl, Python, Node, Go and Git trust the CA bundle on disk; Scott Helme forged an api.stripe.com cert that all three accepted on Linux and macOS, and Firefox on Android and never-updated devices stay exposed until July 2039 (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=226s" target="_blank" rel="noopener">3:46</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=315s" target="_blank" rel="noopener">5:15</a>)</li><li><strong>Cleanup:</strong> Cloudflare patched WARP, 1.1.1.1 and its tunnel on 20 Oct, Go blocked the intermediates in its standard library, Mozilla is removing eMudhra&#39;s root and Chrome follows on 27 Oct, leaving ~30,000 certs a week to migrate (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=315s" target="_blank" rel="noopener">5:15</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=378s" target="_blank" rel="noopener">6:18</a>)</li><li><strong>What to do:</strong> Update your CI&#39;s CA certificates package, bump certifi to 2026.10.19 and Go to 1.27.3, rebuild container images, and run the test curl from the video, which should fail with a certificate error (<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=401s" target="_blank" rel="noopener">6:41</a>–<a href="https://www.youtube.com/watch?v=yW1RnJ5oaMk&amp;t=426s" target="_blank" rel="noopener">7:06</a>)</li></ul></div></article><article class="it full" id="v-PQN76wcEt10" data-title="God&#39;s Eye View: The Open-Source Spy Satellite Simulator" data-channel="Better Stack" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=PQN76wcEt10" target="_blank" rel="noopener"><img src="'+w+'" srcset="'+N+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=PQN76wcEt10" target="_blank" rel="noopener">God&#39;s Eye View: The Open-Source Spy Satellite Simulator</a></h3><div class="meta">Better Stack · Josh · uploaded 22 Oct, 6:00 PM IST · 6:29</div><div class="verdict v-skim"><b>Verdict:</b> skim — fun demo; worth cloning only if you build with maps or live feeds.</div><p class="note">---</p><div class="sh">What it is</div><ul><li><strong>Public feeds on one globe:</strong> An open-source repo (~55,000 stars, trending again) that puts live planes (ADS-B via OpenSky), ships (AIS), satellites (CelesTrak orbits), USGS earthquakes and traffic cameras on a 3D globe, with zero API keys (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=22s" target="_blank" rel="noopener">0:22</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=80s" target="_blank" rel="noopener">1:20</a>)</li><li><strong>Demo:</strong> Click a plane and press C to sit in the cockpit, switch night vision/thermal/CRT views, ride along with the ISS, or view a live traffic camera placed in a 3D city (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=80s" target="_blank" rel="noopener">1:20</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=115s" target="_blank" rel="noopener">1:55</a>)</li><li><strong>Setup:</strong> Clone, `npm ci`, `npm run doctor`, `npm run dev`; it needs Node 24.14+ and doesn&#39;t support Node 25 (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=115s" target="_blank" rel="noopener">1:55</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=135s" target="_blank" rel="noopener">2:15</a>)</li></ul><div class="sh">How it works</div><ul><li><strong>Live data is never live:</strong> Vanilla JS, CesiumJS and Vite with a small Node proxy; feeds update every 15–30 seconds, so the globe runs one update behind and glides between positions, uses dead reckoning when a feed drops, SGP4 for orbits, and rations the free OpenSky budget (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=135s" target="_blank" rel="noopener">2:15</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=195s" target="_blank" rel="noopener">3:15</a>)</li><li><strong>v2.2 (3 Oct):</strong> Added an MCP server so Claude, Codex or ChatGPT can move the globe, grew cameras from ~800 to 3,400, added NASA before/after imagery and iPhone/iPad support; voice uses OpenAI&#39;s Realtime API on your key with a $5 hard stop (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=195s" target="_blank" rel="noopener">3:15</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=235s" target="_blank" rel="noopener">3:55</a>)</li></ul><div class="sh">The catch</div><ul><li><strong>Not real spy imagery:</strong> Ground imagery is ordinary maps, cars are simulated, camera positions are estimates, photoreal 3D needs a Cesium ion or Google Maps key, and the code is MIT but OpenSky and undersea-cable data are non-commercial (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=262s" target="_blank" rel="noopener">4:22</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=330s" target="_blank" rel="noopener">5:30</a>)</li><li><strong>Privacy line:</strong> It refuses to track people, but thousands of cameras next to license-plate-reader locations is still chilling (<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=330s" target="_blank" rel="noopener">5:30</a>–<a href="https://www.youtube.com/watch?v=PQN76wcEt10&amp;t=352s" target="_blank" rel="noopener">5:52</a>)</li></ul></div></article><article class="it full" id="v-Gxi_n-PtQBo" data-title="A PHP Bug Just Took Websites Offline Worldwide" data-channel="Better Stack" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=Gxi_n-PtQBo" target="_blank" rel="noopener"><img src="'+d+'" srcset="'+E+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">Better Stack</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo" target="_blank" rel="noopener">A PHP Bug Just Took Websites Offline Worldwide</a></h3><div class="meta">Better Stack · uploaded 22 Oct, 7:30 AM IST · 7:07</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — big, fresh security story; patch any PHP server you have.</div><div class="sh">The bug</div><ul><li><strong>PHP2Shell:</strong> Two bugs in PHP itself, rated 9.2, where a request that runs PHP out of memory at the wrong moment leaves half-built data that PHP later trusts, enabling unauthenticated remote code execution; Wiz showed it on fresh WordPress, Drupal and Joomla installs and says every PHP version of the last decade is affected (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=30s" target="_blank" rel="noopener">0:30</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=89s" target="_blank" rel="noopener">1:29</a>)</li><li><strong>Leaked disclosure:</strong> The CVEs hit Hacker News early with a wrong 10/10 score, Calif accidentally published an exploit video, and Chainguard shipped patched images 6+ hours early, which the PHP Foundation says broke the embargo (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=89s" target="_blank" rel="noopener">1:29</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=144s" target="_blank" rel="noopener">2:24</a>)</li></ul><div class="sh">The fallout</div><ul><li><strong>Sites taken offline:</strong> The NSA, CISA, FBI and UK NCSC told organisations to take unpatched systems offline; DigiD and the Dutch parliament site, Edinburgh, Bristol and Oxford, parts of Wikimedia, 4chan, Something Awful, Levels&#39; business servers and even BreachForums went dark (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=144s" target="_blank" rel="noopener">2:24</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=219s" target="_blank" rel="noopener">3:39</a>)</li><li><strong>No confirmed hacks yet:</strong> Cloudflare and others got weeks of notice and enabled WAF rules for all customers; watchTowr sees AI-built exploit attempts but no successes, and CISA agrees, but only PHP 8.2+ got proper releases and one scan found 59% of servers on 8.1 or older (Debian/Ubuntu packages were patched back to 7.4) (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=219s" target="_blank" rel="noopener">3:39</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=265s" target="_blank" rel="noopener">4:25</a>)</li></ul><div class="sh">AI found it, maybe</div><ul><li><strong>Who found it:</strong> OpenAI says Calif found it with GPT-5.6 Sol in its &quot;patch the planet&quot; program, Wiz credits Gemini 4 Argon, and Calif says a human researcher was first (5 Aug tweet) with no special models; a 2024 PHP Foundation audit had already spotted early signs and a Claude Mythos scan missed it (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=265s" target="_blank" rel="noopener">4:25</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=340s" target="_blank" rel="noopener">5:40</a>)</li><li><strong>More to come:</strong> The same day Node.js patched an RCE, GitLab fixed a 10/10 bug, and Railway disclosed a breach of stored customer environment variables, which it links to attacks aimed at AI provider keys; his takeaway is that disclosure timelines assume finding bugs is hard, which AI has changed (<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=340s" target="_blank" rel="noopener">5:40</a>–<a href="https://www.youtube.com/watch?v=Gxi_n-PtQBo&amp;t=427s" target="_blank" rel="noopener">7:07</a>)</li></ul></div></article></div>',1))])}const j=m(W,[["render",U]]);export{J as __pageData,j as default};
